INSERT INTO `mitre_attack_techniques` VALUES (1,'T1190','Exploit Public-Facing Application','Initial Access','Adversaries exploit weaknesses in internet-facing systems.'),(2,'T1110','Brute Force','Credential Access','Adversaries use brute force techniques to gain access to accounts.'),(3,'T1595','Active Scanning','Reconnaissance','Adversaries scan victim infrastructure for vulnerabilities.'),(4,'T1566','Phishing','Initial Access','Adversaries send phishing messages to gain access.'),(5,'T1486','Data Encrypted for Impact','Impact','Adversaries encrypt data on target systems (ransomware).'),(6,'T1046','Network Service Discovery','Discovery','Adversaries attempt to get a listing of services running on hosts (port scanning).'),(7,'T1059','Command and Scripting Interpreter','Execution','Adversaries abuse command interpreters to execute commands (SQLi/XSS payload delivery).'),(8,'T1078','Valid Accounts','Defense Evasion','Adversaries use compromised credentials, often linked to insider threats.'),(9,'T1498','Network Denial of Service','Impact','Adversaries flood a target network/service with traffic to degrade or deny availability (DDoS).'),(10,'T1105','Ingress Tool Transfer','Command and Control','Adversaries transfer malicious tools/payloads onto a compromised host from an external system.');
