--
-- Table structure for table `response_actions`
--

DROP TABLE IF EXISTS `response_actions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `response_actions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `incident_id` bigint DEFAULT NULL,
  `threat_id` bigint DEFAULT NULL,
  `action_type` enum('BLOCK_IP','DISABLE_USER','QUARANTINE_THREAT','NOTIFY_ADMIN','GENERATE_INCIDENT') COLLATE utf8mb4_unicode_ci NOT NULL,
  `target` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('PENDING','SUCCESS','FAILED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `triggered_by` enum('AUTOMATED','MANUAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AUTOMATED',
  `performed_by` bigint DEFAULT NULL,
  `details` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `incident_id` (`incident_id`),
  KEY `threat_id` (`threat_id`),
  KEY `performed_by` (`performed_by`),
  CONSTRAINT `response_actions_ibfk_1` FOREIGN KEY (`incident_id`) REFERENCES `incidents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `response_actions_ibfk_2` FOREIGN KEY (`threat_id`) REFERENCES `threats` (`id`) ON DELETE CASCADE,
  CONSTRAINT `response_actions_ibfk_3` FOREIGN KEY (`performed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

