  `threat_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_login_attempts` int DEFAULT NULL,
  `traffic_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_role` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `performed_by` bigint DEFAULT NULL,
  `result_threat_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK3c4gkruaxr7moojv9sbj1eiqx` (`performed_by`),
  KEY `FK6427vt0d9m36nkej5yyv347m6` (`result_threat_id`),
