CREATE TABLE `threats` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `threat_type` enum('MALWARE','DDOS','SQL_INJECTION','XSS','BRUTE_FORCE','PORT_SCAN','PHISHING','RANSOMWARE','INSIDER_THREAT','UNKNOWN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity` enum('LOW','MEDIUM','HIGH','CRITICAL') COLLATE utf8mb4_unicode_ci NOT NULL,
  `confidence_score` decimal(38,2) NOT NULL,
  `source_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `destination_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_port` int DEFAULT NULL,
  `destination_port` int DEFAULT NULL,
  `protocol` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `affected_user_id` bigint DEFAULT NULL,
  `recommended_action` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('DETECTED','ANALYZING','MITIGATED','FALSE_POSITIVE','IGNORED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DETECTED',
  `raw_payload` text COLLATE utf8mb4_unicode_ci,
  `detected_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `cve_record_id` bigint DEFAULT NULL,
  `contributing_factors` text COLLATE utf8mb4_unicode_ci,
  `reasoning` text COLLATE utf8mb4_unicode_ci,
  `risk_score` decimal(38,2) DEFAULT NULL,
  `shap_explanation` text COLLATE utf8mb4_unicode_ci,
  `cross_model_agreement` enum('AGREE','DISAGREE','UNAVAILABLE') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `temporal_category` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `affected_user_id` (`affected_user_id`),
  KEY `cve_record_id` (`cve_record_id`),
  KEY `idx_threats_detected_at` (`detected_at`),
  KEY `idx_threats_type` (`threat_type`),
  KEY `idx_threats_severity` (`severity`),
  CONSTRAINT `threats_ibfk_1` FOREIGN KEY (`affected_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `threats_ibfk_2` FOREIGN KEY (`cve_record_id`) REFERENCES `cve_records` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
